/** Calculator UI controller. Battle formulas remain in engine.mjs. */
export function setupCalculator(ctx){
  const {$,stats,row,team,makeSet,data,toast,damageBenchmark,actualStats,master,itemPower,abilityPower,esc,evtext,koreanType,multiplier,strongestStatMove,damageScenarioResults,speedVariants}=ctx;
  function renderMoves(){const pokemon=row($('calcAtk').value.trim()),set=pokemon?(team().find(x=>x?.name===pokemon.name)||makeSet(pokemon)):null,moves=(set?.moves||[]).map(name=>data.master.moves.find(x=>x[0]===name)).filter(move=>move&&move[3]!=='변화'&&Number(move[4])>0);$('calcMove').innerHTML=moves.map(move=>`<option value="${esc(move[0])}">${esc(move[0])} · ${esc(koreanType[move[2]]||move[2])} · 위력 ${move[4]}</option>`).join('')||'<option value="">공격 기술 없음</option>'}
  function renderNames(){$('calcMons').innerHTML=stats().map(p=>`<option value="${esc(p.name)}"></option>`).join('');if(!row($('calcAtk').value))$('calcAtk').value=team().find(Boolean)?.name||stats()[0].name;if(!row($('calcDef').value))$('calcDef').value=stats()[1].name;renderMoves()}
  function pair(){const attacker=row($('calcAtk').value.trim()),defender=row($('calcDef').value.trim());if(!attacker||!defender){toast('현재 챔피언스 목록에서 공격·방어 포켓몬을 선택해 주세요.');return null}return {attacker,defender}}
  function run(){const current=pair();if(!current)return;const {attacker,defender}=current,move=data.master.moves.find(x=>x[0]===$('calcMove').value);if(!move)return toast('계산할 공격 기술을 선택해 주세요.');const set=team().find(x=>x?.name===attacker.name)||makeSet(attacker),evs=$('calcBulk').value.split(',').map(Number),result=damageBenchmark(set,defender,move,evs),actual=actualStats(set),zero=actualStats(set,[0,0,0,0,0,0]),type=koreanType[move[2]]||move[2],stab=attacker.types.includes(type)?(set.abilities==='적응력'?2:1.5):1,power=Math.round((move[3]==='물리'?actual[1]:actual[3])*Number(move[4])*stab*itemPower(set.items,type,move[3])*abilityPower(set.abilities,type,move[3])),physical=Math.round(actual[0]*actual[2]),special=Math.round(actual[0]*actual[4]),speed=Math.floor(actual[5]*(set.items==='구애스카프'?1.5:1)),bench=stats().slice(0,20),beat0=bench.filter(p=>speed>Number(master(p.name)[8])+20).length,beat32=bench.filter(p=>speed>Number(master(p.name)[8])+52).length;$('calcResult').innerHTML=`<h3>${esc(attacker.name)} → ${esc(defender.name)}</h3><p><b>${esc(move[0])}</b> · ${esc(type)} · ${esc(move[3])} · 자속 ×${stab} · 타입상성 ×${multiplier(type,defender.types)}</p><div class="calccards"><article><small>데미지</small><strong>${result.minPct}~${result.maxPct}%</strong><b>${esc(result.label)}</b></article><article><small>결정력 지수</small><strong>${power.toLocaleString()}</strong><b>공격 수치·위력·자속·도구·특성</b></article><article><small>내구력</small><strong>${physical.toLocaleString()} / ${special.toLocaleString()}</strong><b>물리 / 특수 · 무투자 대비 ${Math.round((physical/(zero[0]*zero[2])-1)*100)}% / ${Math.round((special/(zero[0]*zero[4])-1)*100)}%</b></article><article><small>스피드 ${speed}</small><strong>S0 ${beat0}종 / S32 ${beat32}종</strong><b>상위 ${bench.length}종보다 빠른 수</b></article></div><p class="leadnotice">86~100의 15개 난수 기준입니다. 명중률·급소·날씨·필드·랭크·벽·가변 위력 등은 제외합니다.</p>`}
  function runPowerSweep(){const current=pair();if(!current)return;const {attacker,defender}=current,set=team().find(x=>x?.name===attacker.name)||makeSet(attacker),best=strongestStatMove(attacker,defender,set,data.master);if(!best)return toast('채용률 상위 4개 기술에서 계산 가능한 공격기를 찾지 못했습니다.');const lines=damageScenarioResults(attacker,defender,set,best.move,data.master).map(({label,calc})=>`<article><small>${esc(label)}</small><strong>${calc.result.minPct}~${calc.result.maxPct}%</strong><b>${esc(calc.result.label)} · ${calc.result.min}~${calc.result.max}</b></article>`).join('');$('calcResult').innerHTML=`<h3>${esc(attacker.name)} → ${esc(defender.name)} 결정력 일괄 계산</h3><p><b>${esc(best.move[0])}</b> · 채용률 ${best.rate}% · ${esc(best.calc.type)}/${esc(best.calc.category)} · 위력 ${best.move[4]} · 자속 ×${best.calc.stab} · 타입상성 ×${best.calc.typeMultiplier}</p><p>${esc(set.items||'도구 없음')} / ${esc(set.abilities||'특성 없음')} / ${esc(set.natures||'성격 없음')} / ${esc(evtext(set.evs))}</p><div class="calccards sweepcards">${lines}</div><p class="leadnotice">채용률 상위 4개 기술 중 대상에게 최대 피해를 주는 공격기를 사용합니다. 방어 성격은 무보정이며 조건부 효과·연속기 횟수·가변 위력 등은 제외합니다.</p>`}
  function runSpeedCompare(){const current=pair();if(!current)return;const {attacker,defender}=current,left=speedVariants(attacker,data.master),right=speedVariants(defender,data.master);if(!left||!right)return toast('현재 챔피언스 데이터로 스피드를 계산할 수 없습니다.');const lines=left.map((a,i)=>{const b=right[i],mark=a.value===b.value?'＝':a.value>b.value?'＞':'＜',winner=a.value===b.value?'동속':a.value>b.value?attacker.name:defender.name;return `<article><small>${esc(a.label)}</small><strong>${a.value} ${mark} ${b.value}</strong><b>${esc(attacker.name)} / ${esc(defender.name)} · ${esc(winner)}</b></article>`}).join('');$('calcResult').innerHTML=`<h3>${esc(attacker.name)} ↔ ${esc(defender.name)} 스피드 비교</h3><div class="calccards speedcards">${lines}</div><p class="leadnotice">최속은 S32+스피드 상승 성격, 준속은 S32 무보정 성격, 무보정은 S0입니다. 스카프는 해당 수치에 ×1.5 후 버림합니다.</p>`}
  $('calcAtk').addEventListener('change',renderMoves);$('calcRun').onclick=run;$('calcPowerSweep').onclick=runPowerSweep;$('calcSpeedCompare').onclick=runSpeedCompare;
  return {renderNames,renderMoves};
}
